const IN_APP = self.location.hostname === 'localhost';
self.addEventListener('install', e => { if (IN_APP) { self.skipWaiting(); return; } e.waitUntil(caches.open(V).then(c => c.addAll(FILES)).then(() => self.skipWaiting())); });
self.addEventListener('activate', e => { if (IN_APP) { e.waitUntil(caches.keys().then(ks => Promise.all(ks.map(k => caches.delete(k)))).then(() => self.registration.unregister()).then(() => self.clients.matchAll()).then(cs => cs.forEach(c => c.navigate(c.url)))); return; } e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== V).map(k => caches.delete(k)))).then(() => self.clients.claim())); });
self.addEventListener('fetch', e => {
  const u = new URL(e.request.url);
  if (IN_APP || u.origin !== location.origin) return;   // 바깥(검색·날씨·AI)은 그대로
  e.respondWith(fetch(e.request).then(r => { const c = r.clone(); caches.open(V).then(cc => cc.put(e.request, c)); return r; }).catch(() => caches.match(e.request)));   // 새것 먼저, 인터넷 없으면 보관한 것
});
